package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonPOJOBuilder;
import com.fasterxml.jackson.databind.cfg.ConfigOverride;
import com.fasterxml.jackson.databind.cfg.DeserializerFactoryConfig;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.impl.*;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.deser.std.ThrowableDeserializer;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.SimpleBeanPropertyDefinition;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class BeanDeserializerFactory_createBeanDeserializer_TriageGen0Test {

    private BeanDeserializerFactory factory;
    private DeserializationContext ctxt;
    private DeserializationConfig config;
    private JavaType type;
    private BeanDescription beanDesc;
    private TypeFactory typeFactory;

    // A concrete class to act as a potential bean
    public static class TestBean {
        public String name;
    }

    // An abstract class for materialization testing
    public static abstract class AbstractBean {
        public String value;
    }

    public static class ConcreteBean extends AbstractBean {}

    // A Throwable subclass
    public static class TestException extends RuntimeException {}

    @Before
    public void setUp() {
        factory = mock(BeanDeserializerFactory.class, CALLS_REAL_METHODS);
        ctxt = mock(DeserializationContext.class);
        config = mock(DeserializationConfig.class);
        type = mock(JavaType.class);
        beanDesc = mock(BeanDescription.class);
        typeFactory = TypeFactory.defaultInstance();

        when(ctxt.getConfig()).thenReturn(config);
    }

    @Test
    public void testCreateBeanDeserializer_CustomOverrideFound() throws JsonMappingException {
        JsonDeserializer<Object> customDeser = new StdDeserializer<Object>(Object.class) {};

        // Use a spy to control the protected _findCustomBeanDeserializer
        BeanDeserializerFactory spyFactory = spy(factory);
        doReturn(customDeser).when(spyFactory)._findCustomBeanDeserializer(any(), any(), any());

        JsonDeserializer<Object> result = spyFactory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(customDeser, result);
        verify(spyFactory)._findCustomBeanDeserializer(type, config, beanDesc);
    }

    @Test
    public void testCreateBeanDeserializer_ThrowableType() throws JsonMappingException {
        when(_findCustomBeanDeserializer(any(), any(), any())).thenReturn(null);
        when(type.isThrowable()).thenReturn(true);

        BeanDeserializerFactory spyFactory = spy(factory);
        doReturn(null).when(spyFactory)._findCustomBeanDeserializer(any(), any(), any());

        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);
        doReturn(expectedDeser).when(spyFactory).buildThrowableDeserializer(ctxt, type, beanDesc);

        JsonDeserializer<Object> result = spyFactory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(expectedDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_AbstractTypeMaterialized() throws JsonMappingException {
        when(_findCustomBeanDeserializer(any(), any(), any())).thenReturn(null);
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(true);
        when(type.isPrimitive()).thenReturn(false);
        when(type.isEnumType()).thenReturn(false);

        JavaType concreteType = typeFactory.constructType(ConcreteBean.class);

        BeanDeserializerFactory spyFactory = spy(factory);
        doReturn(null).when(spyFactory)._findCustomBeanDeserializer(any(), any(), any());
        doReturn(concreteType).when(spyFactory).materializeAbstractType(ctxt, type, beanDesc);
        when(config.introspect(concreteType)).thenReturn(beanDesc);

        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);
        doReturn(expectedDeser).when(spyFactory).buildBeanDeserializer(ctxt, concreteType, beanDesc);

        JsonDeserializer<Object> result = spyFactory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(expectedDeser, result);
        verify(config).introspect(concreteType);
    }

    @Test
    public void testCreateBeanDeserializer_AbstractTypeNoMaterialization() throws JsonMappingException {
        when(_findCustomBeanDeserializer(any(), any(), any())).thenReturn(null);
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(true);
        when(type.isPrimitive()).thenReturn(false);
        when(type.isEnumType()).thenReturn(false);

        BeanDeserializerFactory spyFactory = spy(factory);
        doReturn(null).when(spyFactory).materializeAbstractType(any(), any(), any());

        // Fallthrough to findStdDeserializer
        doReturn(null).when(spyFactory).findStdDeserializer(any(), any(), any());
        // Mock isPotentialBeanType to return false for the abstract type
        doReturn(false).when(spyFactory).isPotentialBeanType(any());

        JsonDeserializer<Object> result = spyFactory.createBeanDeserializer(ctxt, type, beanDesc);

        assertNull(result);
    }

    @Test
    public void testCreateBeanDeserializer_StdDeserializerFound() throws JsonMappingException {
        when(_findCustomBeanDeserializer(any(), any(), any())).thenReturn(null);
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(false);

        JsonDeserializer<Object> stdDeser = mock(JsonDeserializer.class);
        BeanDeserializerFactory spyFactory = spy(factory);
        doReturn(null).when(spyFactory)._findCustomBeanDeserializer(any(), any(), any());
        doReturn(stdDeser).when(spyFactory).findStdDeserializer(ctxt, type, beanDesc);

        JsonDeserializer<Object> result = spyFactory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(stdDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_PotentialBeanTypeFallback() throws JsonMappingException {
        when(_findCustomBeanDeserializer(any(), any(), any())).thenReturn(null);
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(false);

        Class<?> rawClass = TestBean.class;
        when(type.getRawClass()).thenReturn(rawClass);

        BeanDeserializerFactory spyFactory = spy(factory);
        doReturn(null).when(spyFactory)._findCustomBeanDeserializer(any(), any(), any());
        doReturn(null).when(spyFactory).findStdDeserializer(any(), any(), any());
        doReturn(true).when(spyFactory).isPotentialBeanType(rawClass);

        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);
        doReturn(expectedDeser).when(spyFactory).buildBeanDeserializer(ctxt, type, beanDesc);

        JsonDeserializer<Object> result = spyFactory.createBeanDeserializer(ctxt, type, beanDesc);

        assertEquals(expectedDeser, result);
    }

    @Test
    public void testCreateBeanDeserializer_NotAPotentialBeanType() throws JsonMappingException {
        when(_findCustomBeanDeserializer(any(), any(), any())).thenReturn(null);
        when(type.isThrowable()).thenReturn(false);
        when(type.isAbstract()).thenReturn(false);

        Class<?> rawClass = String.class;
        when(type.getRawClass()).thenReturn(rawClass);

        BeanDeserializerFactory spyFactory = spy(factory);
        doReturn(null).when(spyFactory)._findCustomBeanDeserializer(any(), any(), any());
        doReturn(null).when(spyFactory).findStdDeserializer(any(), any(), any());
        doReturn(false).when(spyFactory).isPotentialBeanType(rawClass);

        JsonDeserializer<Object> result = spyFactory.createBeanDeserializer(ctxt, type, beanDesc);

        assertNull(result);
    }

    // Helper to mock the protected _findCustomBeanDeserializer which isn't in the provided list but used in code
    private JsonDeserializer<Object> _findCustomBeanDeserializer(JavaType type, DeserializationConfig config, BeanDescription beanDesc) {
        return null;
    }
}
